-- Migrações 30 e 31 (cw_nonprod): escritórios, papel Assistente e dono da plataforma. Cole no SQL Editor e execute (duas transações: a 30 precisa terminar antes da 31).
begin;
-- GENERATED by scripts/gen-migrations.mjs from supabase/templates. Do not edit by hand.
-- Gate 21a (D-056): new office role. Kept in its own migration: a new enum value can only be used after the
-- transaction that adds it commits.
--   ASSISTANT  every client of the office, CRM and planning work only; no settings, no team or user management.
-- The platform owner (Master) is not a role but a flag on the profile (Gate 21b): the owner keeps working as the ADMIN
-- of his own office and, separately, manages offices and global rules.
alter type cw_nonprod.app_role add value if not exists 'ASSISTANT';
commit;
begin;
-- GENERATED by scripts/gen-migrations.mjs from supabase/templates. Do not edit by hand.
-- Gate 21b (D-056): several offices on one platform. Every office is a tenant: its people, clients and CRM contacts
-- carry office_id, and every access predicate (can_access_client / can_access_contact / RLS / admin RPCs) now also
-- requires the same office. Existing data moves to the first office ("Campos Wealth"). Additive and idempotent per row.
--   Office roles: ADMIN (the whole office, management), CONSULTANT (own clients), ASSISTANT (every client of the
--   office, CRM and planning only), CLIENT (own planning). Platform owner ("Master"): profiles.platform_master, set
--   only by the operator in SQL; manages offices and global rules, and reaches another office's client data only
--   through a time-boxed, justified support session recorded in the audit trail.

-- ---------------------------------------------------------------- offices
create table cw_nonprod.offices (
  id          uuid primary key default gen_random_uuid(),
  name        text not null check (length(btrim(name)) between 2 and 120),
  legal_name  text check (length(legal_name) <= 200),
  cnpj        text check (cnpj ~ '^[0-9]{14}$'),
  cvm_code    text check (length(cvm_code) <= 40),
  status      text not null default 'ACTIVE' check (status in ('ACTIVE', 'SUSPENDED')),
  created_by  uuid,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);
create unique index offices_cnpj_key on cw_nonprod.offices (cnpj) where cnpj is not null;
insert into cw_nonprod.offices (name) select 'Campos Wealth' where not exists (select 1 from cw_nonprod.offices);

alter table cw_nonprod.profiles add column office_id uuid references cw_nonprod.offices (id);
alter table cw_nonprod.profiles add column platform_master boolean not null default false;
alter table cw_nonprod.clients add column office_id uuid references cw_nonprod.offices (id);
alter table cw_nonprod.crm_contacts add column office_id uuid references cw_nonprod.offices (id);
alter table cw_nonprod.invitations add column office_id uuid references cw_nonprod.offices (id);
create index on cw_nonprod.profiles (office_id);
create index on cw_nonprod.clients (office_id);
create index on cw_nonprod.crm_contacts (office_id);
create index on cw_nonprod.invitations (office_id);

-- backfill: everything that exists belongs to the first office
select set_config('cw.privileged', 'on', true);
update cw_nonprod.profiles set office_id = (select id from cw_nonprod.offices order by created_at, id limit 1) where office_id is null;
update cw_nonprod.clients set office_id = (select id from cw_nonprod.offices order by created_at, id limit 1) where office_id is null;
update cw_nonprod.crm_contacts set office_id = (select id from cw_nonprod.offices order by created_at, id limit 1) where office_id is null;
update cw_nonprod.invitations set office_id = (select id from cw_nonprod.offices order by created_at, id limit 1) where office_id is null;
-- The platform owner: where the environment has exactly one ADMIN and no owner yet, that ADMIN (the person who set the
-- platform up) becomes the owner. Anywhere else it stays off until the operator sets it in SQL.
update cw_nonprod.profiles set platform_master = true
 where role = 'ADMIN' and status = 'ACTIVE'
   and (select count(*) from cw_nonprod.profiles where role = 'ADMIN') = 1
   and not exists (select 1 from cw_nonprod.profiles where platform_master);
select set_config('cw.privileged', '', true);
alter table cw_nonprod.profiles alter column office_id set not null;
alter table cw_nonprod.clients alter column office_id set not null;
alter table cw_nonprod.crm_contacts alter column office_id set not null;
alter table cw_nonprod.invitations alter column office_id set not null;
alter table cw_nonprod.invitations drop constraint if exists invitations_role_check;
alter table cw_nonprod.invitations add constraint invitations_role_check check (role in ('ADMIN', 'CONSULTANT', 'ASSISTANT', 'CLIENT'));

-- ---------------------------------------------------------------- identity helpers
-- A suspended office or an inactive profile has no role at all (fail closed everywhere my_role() is used).
create or replace function cw_nonprod_private.my_role() returns cw_nonprod.app_role
language sql stable security definer set search_path = '' as $$
  select p.role from cw_nonprod.profiles p join cw_nonprod.offices o on o.id = p.office_id
   where p.id = (select auth.uid()) and p.status = 'ACTIVE' and o.status = 'ACTIVE'
$$;

create function cw_nonprod_private.my_office() returns uuid
language sql stable security definer set search_path = '' as $$
  select p.office_id from cw_nonprod.profiles p join cw_nonprod.offices o on o.id = p.office_id
   where p.id = (select auth.uid()) and p.status = 'ACTIVE' and o.status = 'ACTIVE'
$$;

create function cw_nonprod_private.office_of_user(p_user uuid) returns uuid
language sql stable security definer set search_path = '' as $$
  select office_id from cw_nonprod.profiles where id = p_user
$$;

create function cw_nonprod_private.is_master() returns boolean
language sql stable security definer set search_path = '' as $$
  select coalesce((select p.platform_master from cw_nonprod.profiles p where p.id = (select auth.uid()) and p.status = 'ACTIVE'), false)
     and cw_nonprod_private.staff_aal_ok()
$$;

create or replace function cw_nonprod_private.is_staff() returns boolean
language sql stable security definer set search_path = '' as $$
  select coalesce(cw_nonprod_private.my_role() in ('ADMIN', 'CONSULTANT', 'ASSISTANT') and cw_nonprod_private.staff_aal_ok(), false)
$$;

-- ---------------------------------------------------------------- support sessions (Master, internal audit only)
create table cw_nonprod_private.support_sessions (
  id          uuid primary key default gen_random_uuid(),
  master_id   uuid not null references cw_nonprod.profiles (id),
  office_id   uuid not null references cw_nonprod.offices (id),
  reason      text not null check (length(btrim(reason)) between 10 and 500),
  started_at  timestamptz not null default now(),
  expires_at  timestamptz not null,
  ended_at    timestamptz,
  check (expires_at > started_at and expires_at <= started_at + interval '2 hours')
);
create index on cw_nonprod_private.support_sessions (master_id, office_id) where ended_at is null;
alter table cw_nonprod_private.support_sessions enable row level security;
alter table cw_nonprod_private.support_sessions force row level security;
revoke all on cw_nonprod_private.support_sessions from public, anon, authenticated;
grant all on cw_nonprod_private.support_sessions to service_role;

create function cw_nonprod_private.support_access(p_office uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select cw_nonprod_private.is_master() and exists (
    select 1 from cw_nonprod_private.support_sessions s
     where s.master_id = (select auth.uid()) and s.office_id = p_office and s.ended_at is null and s.expires_at > now())
$$;

-- ---------------------------------------------------------------- access predicates, now office-bound
create or replace function cw_nonprod_private.can_access_client(p_client_id uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select coalesce((
    select case r.role
      when 'ADMIN' then cw_nonprod_private.staff_aal_ok() and c.status <> 'PURGED' and c.office_id = r.office_id
      when 'ASSISTANT' then cw_nonprod_private.staff_aal_ok() and c.status <> 'PURGED' and c.office_id = r.office_id
      when 'CONSULTANT' then cw_nonprod_private.staff_aal_ok() and c.status <> 'PURGED' and c.office_id = r.office_id and exists (
        select 1 from cw_nonprod.consultant_client_access a
        where a.consultant_id = r.id and a.client_id = c.id and a.status = 'ACTIVE')
      when 'CLIENT' then c.status = 'ACTIVE' and exists (
        select 1 from cw_nonprod.client_users u where u.user_id = r.id and u.client_id = c.id)
    end
    from cw_nonprod.profiles r join cw_nonprod.offices o on o.id = r.office_id, cw_nonprod.clients c
    where r.id = (select auth.uid()) and r.status = 'ACTIVE' and o.status = 'ACTIVE' and c.id = p_client_id), false)
  or coalesce((select c.status <> 'PURGED' and cw_nonprod_private.support_access(c.office_id) from cw_nonprod.clients c where c.id = p_client_id), false)
$$;

create or replace function cw_nonprod_private.can_access_contact(p_contact uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select coalesce((
    select case cw_nonprod_private.my_role()
      when 'ADMIN' then cw_nonprod_private.staff_aal_ok() and c.office_id = cw_nonprod_private.my_office()
      when 'ASSISTANT' then cw_nonprod_private.staff_aal_ok() and c.office_id = cw_nonprod_private.my_office()
      when 'CONSULTANT' then cw_nonprod_private.staff_aal_ok() and c.office_id = cw_nonprod_private.my_office()
        and (c.owner_id = (select auth.uid()) or (c.client_id is not null and cw_nonprod_private.can_access_client(c.client_id)))
      else false end
    from cw_nonprod.crm_contacts c where c.id = p_contact), false)
  or coalesce((select cw_nonprod_private.support_access(c.office_id) from cw_nonprod.crm_contacts c where c.id = p_contact), false)
$$;

-- CRM owner reassignment (ADMIN): only an active staff member of the same office.
create or replace function cw_nonprod_private.crm_owner(p_owner uuid) returns uuid
language plpgsql stable security definer set search_path = '' as $$
begin
  if cw_nonprod_private.my_role() = 'ADMIN' and p_owner is not null then
    if not exists (select 1 from cw_nonprod.profiles where id = p_owner and role in ('ADMIN', 'CONSULTANT', 'ASSISTANT')
                    and status = 'ACTIVE' and office_id = cw_nonprod_private.my_office()) then
      perform cw_nonprod_private.deny();
    end if;
    return p_owner;
  end if;
  return auth.uid();
end $$;

-- ---------------------------------------------------------------- office stamping and cross-office guards
-- New rows inherit the office of whoever creates them (or of the CRM owner / the inviting staff member).
-- Named a_* so it fires before the t_guard_office check (same-event triggers run in name order).
create function cw_nonprod_private.stamp_office() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if new.office_id is null then
    if tg_table_name = 'crm_contacts' then new.office_id := coalesce(cw_nonprod_private.office_of_user(new.owner_id), cw_nonprod_private.my_office());
    elsif tg_table_name = 'invitations' then new.office_id := coalesce(cw_nonprod_private.my_office(), cw_nonprod_private.office_of_user(new.invited_by));
    else new.office_id := cw_nonprod_private.my_office(); end if;
  end if;
  if new.office_id is null then raise exception 'office required' using errcode = '42501'; end if;
  return new;
end $$;
create trigger a_stamp_office before insert on cw_nonprod.clients for each row execute function cw_nonprod_private.stamp_office();
create trigger a_stamp_office before insert on cw_nonprod.crm_contacts for each row execute function cw_nonprod_private.stamp_office();
create trigger a_stamp_office before insert on cw_nonprod.invitations for each row execute function cw_nonprod_private.stamp_office();

-- A new profile belongs to the office of its invitation; the operator bootstrap (no invitation) to the first office.
create function cw_nonprod_private.stamp_profile_office() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if new.office_id is null then
    new.office_id := coalesce(
      (select i.office_id from cw_nonprod.invitations i where i.auth_user_id = new.id and i.status = 'PENDING' order by i.created_at desc limit 1),
      (select id from cw_nonprod.offices order by created_at, id limit 1));
  end if;
  return new;
end $$;
create trigger a_stamp_office before insert on cw_nonprod.profiles for each row execute function cw_nonprod_private.stamp_profile_office();

-- Rows written by a signed-in person must stay inside that person's office (the Master only inside a support session).
-- Service-role jobs (no auth.uid()) are not affected. office_id and platform_master never change through the API.
-- (Function body below, after the Master section, because it also admits the Master's office-admin invitation.)
create function cw_nonprod_private.guard_office() returns trigger language plpgsql as $$ begin return new; end $$;
create trigger t_guard_office before update on cw_nonprod.profiles for each row execute function cw_nonprod_private.guard_office();
create trigger t_guard_office before update on cw_nonprod.clients for each row execute function cw_nonprod_private.guard_office();
create trigger t_guard_office before insert or update on cw_nonprod.crm_contacts for each row execute function cw_nonprod_private.guard_office();
create trigger t_guard_office before insert or update on cw_nonprod.invitations for each row execute function cw_nonprod_private.guard_office();
create trigger t_guard_office before insert or update on cw_nonprod.consultant_client_access for each row execute function cw_nonprod_private.guard_office();
create trigger t_guard_office before insert or update on cw_nonprod.client_users for each row execute function cw_nonprod_private.guard_office();
create trigger t_guard_office before insert or update on cw_nonprod.user_permissions for each row execute function cw_nonprod_private.guard_office();

-- ---------------------------------------------------------------- reads scoped to the office
drop policy profiles_read on cw_nonprod.profiles;
create policy profiles_read on cw_nonprod.profiles for select to authenticated
  using (id = (select auth.uid()) or ((select cw_nonprod_private.is_admin()) and office_id = (select cw_nonprod_private.my_office())) or (select cw_nonprod_private.is_master()));
drop policy user_permissions_read on cw_nonprod.user_permissions;
create policy user_permissions_read on cw_nonprod.user_permissions for select to authenticated
  using (user_id = (select auth.uid()) or ((select cw_nonprod_private.is_admin()) and (select cw_nonprod_private.office_of_user(user_id)) = (select cw_nonprod_private.my_office())));
drop policy access_read on cw_nonprod.consultant_client_access;
create policy access_read on cw_nonprod.consultant_client_access for select to authenticated
  using (((select cw_nonprod_private.is_admin()) and (select cw_nonprod_private.can_access_client(client_id)))
         or (consultant_id = (select auth.uid()) and (select cw_nonprod_private.is_staff())));
drop policy invitations_read on cw_nonprod.invitations;
create policy invitations_read on cw_nonprod.invitations for select to authenticated
  using (((select cw_nonprod_private.is_admin()) and office_id = (select cw_nonprod_private.my_office()))
         or ((select cw_nonprod_private.is_staff()) and (invited_by = (select auth.uid())
             or (client_id is not null and (select cw_nonprod_private.can_access_client(client_id))))));

alter table cw_nonprod.offices enable row level security;
alter table cw_nonprod.offices force row level security;
create policy offices_read on cw_nonprod.offices for select to authenticated
  using (id = (select cw_nonprod_private.my_office()) or (select cw_nonprod_private.is_master()));
revoke all on cw_nonprod.offices from public, anon, authenticated;
grant select on cw_nonprod.offices to authenticated;
grant all on cw_nonprod.offices to service_role;
create trigger t_audit after insert or update or delete on cw_nonprod.offices for each row execute function cw_nonprod_private.audit_row();

-- Users of the office only (identity administration).
create or replace function cw_nonprod.admin_user_overview()
returns table (user_id uuid, full_name text, email text, role text, status text, has_mfa boolean, client_name text)
language plpgsql stable security definer set search_path = '' as $$
begin
  if not cw_nonprod_private.is_admin() then perform cw_nonprod_private.deny(); end if;
  return query
  select p.id, p.full_name, p.email, p.role::text, p.status::text,
         exists (select 1 from auth.mfa_factors f where f.user_id = p.id and f.status = 'verified'),
         (select c.display_name from cw_nonprod.client_users cu join cw_nonprod.clients c on c.id = cu.client_id where cu.user_id = p.id)
  from cw_nonprod.profiles p where p.office_id = cw_nonprod_private.my_office() order by p.role, p.full_name, p.email;
end $$;

-- Audit trail of the office: events on its clients or by its people; the platform owner's support work stays internal.
create or replace function cw_nonprod.admin_audit_log(p_before_id bigint default null, p_limit integer default 50)
returns setof cw_nonprod.audit_logs
language plpgsql stable security definer set search_path = '' as $$
declare v_office uuid := cw_nonprod_private.my_office(); v_master boolean := cw_nonprod_private.is_master();
begin
  if not cw_nonprod_private.is_admin() and not v_master then perform cw_nonprod_private.deny(); end if;
  return query select a.* from cw_nonprod.audit_logs a
    left join cw_nonprod.clients c on c.id = a.client_id
    left join cw_nonprod.profiles p on p.id = a.actor_user_id
    where (p_before_id is null or a.id < p_before_id)
      and (v_master or ((c.office_id = v_office or (a.client_id is null and p.office_id = v_office))
                        and a.action <> 'ADMIN_SUPPORT_ACCESS' and coalesce(p.office_id = v_office, true)))
    order by a.id desc limit least(greatest(p_limit, 1), 100);
end $$;

-- Invitations: ADMIN invites ADMIN, CONSULTANT, ASSISTANT or CLIENT; CONSULTANT and ASSISTANT invite clients they can access.
create or replace function cw_nonprod.create_invitation(p_email text, p_role cw_nonprod.app_role, p_client uuid) returns uuid
language plpgsql security definer set search_path = '' as $$
declare v_me cw_nonprod.app_role := cw_nonprod_private.my_role(); v_email text := lower(trim(p_email)); v_id uuid;
begin
  if not cw_nonprod_private.is_staff() or p_role is null then perform cw_nonprod_private.deny(); end if;
  if v_me in ('CONSULTANT', 'ASSISTANT') and p_role <> 'CLIENT' then perform cw_nonprod_private.deny(); end if;
  if p_role = 'CLIENT' and (p_client is null or not cw_nonprod_private.can_access_client(p_client)) then perform cw_nonprod_private.deny(); end if;
  if p_role <> 'CLIENT' and p_client is not null then perform cw_nonprod_private.deny(); end if;
  if v_email is null or v_email !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' then
    raise exception 'invalid email' using errcode = '22023';
  end if;
  update cw_nonprod.invitations set status = 'REVOKED', revoked_at = now(), revoked_by = auth.uid()
   where email = v_email and status = 'PENDING' and expires_at <= now();
  insert into cw_nonprod.invitations (email, role, client_id, invited_by, office_id)
  values (v_email, p_role, p_client, auth.uid(), cw_nonprod_private.my_office()) returning id into v_id;
  perform cw_nonprod_private.write_audit('INVITE_CREATED', 'invitations', v_id::text, p_client, null, jsonb_build_object('role', p_role));
  return v_id;
end $$;

-- Role changes stay inside the office roles (never CLIENT ⇄ staff with a linked client, never the platform flag).
create or replace function cw_nonprod.admin_set_user_role(p_user uuid, p_role cw_nonprod.app_role) returns void
language plpgsql security definer set search_path = '' as $$
declare v_old cw_nonprod.app_role;
begin
  if not cw_nonprod_private.is_admin() or p_user = auth.uid() or cw_nonprod_private.office_of_user(p_user) is distinct from cw_nonprod_private.my_office() then
    perform cw_nonprod_private.deny();
  end if;
  select role into v_old from cw_nonprod.profiles where id = p_user;
  if not found then perform cw_nonprod_private.deny(); end if;
  if (v_old = 'CLIENT') <> (p_role = 'CLIENT') then
    raise exception 'staff and client accounts are separate' using errcode = '22023';
  end if;
  perform set_config('cw.privileged', 'on', true);
  update cw_nonprod.profiles set role = p_role where id = p_user;
  perform set_config('cw.privileged', '', true);
  perform cw_nonprod_private.write_audit('PERMISSION_CHANGE', 'profiles', p_user::text, null,
    jsonb_build_object('role', v_old), jsonb_build_object('role', p_role));
end $$;

-- ---------------------------------------------------------------- global rules: platform owner only
create or replace function cw_nonprod.admin_publish_tax_rule_set(p_id uuid) returns void
language plpgsql security definer set search_path = '' as $$
begin
  if not cw_nonprod_private.is_master() then perform cw_nonprod_private.deny(); end if;
  update cw_nonprod.tax_rule_sets set published_at = now(), published_by = auth.uid() where id = p_id and published_at is null;
  if not found then perform cw_nonprod_private.deny(); end if;
  perform cw_nonprod_private.write_audit('UPDATE', 'tax_rule_sets', p_id::text, null, null, jsonb_build_object('published', true));
end $$;

create or replace function cw_nonprod.admin_create_tax_rule_set(p_year integer, p_rules jsonb, p_source text, p_notes text) returns uuid
language plpgsql security definer set search_path = '' as $$
declare v_id uuid; v_ver int;
begin
  if not cw_nonprod_private.is_master() then perform cw_nonprod_private.deny(); end if;
  select coalesce(max(version), 0) + 1 into v_ver from cw_nonprod.tax_rule_sets where tax = 'IRPF' and tax_year = p_year;
  insert into cw_nonprod.tax_rule_sets (tax, tax_year, version, rules, source_reference, notes, created_by)
  values ('IRPF', p_year, v_ver, p_rules, btrim(p_source), p_notes, auth.uid()) returning id into v_id;
  perform cw_nonprod_private.write_audit('CREATE', 'tax_rule_sets', v_id::text, null, null, jsonb_build_object('tax_year', p_year, 'version', v_ver));
  return v_id;
end $$;

drop policy rule_sets_read on cw_nonprod.tax_rule_sets;
create policy rule_sets_read on cw_nonprod.tax_rule_sets for select to authenticated
  using (published_at is not null or (select cw_nonprod_private.is_master()));

create or replace function cw_nonprod.itcmd_rule_save(p_uf text, p_rules jsonb, p_source text, p_notes text) returns uuid
language plpgsql security definer set search_path = '' as $$
declare v_id uuid;
begin
  if not cw_nonprod_private.is_master() then perform cw_nonprod_private.deny(); end if;
  insert into cw_nonprod.itcmd_rules (uf, version, rules, source_reference, notes, created_by)
  values (upper(p_uf), coalesce((select max(version) from cw_nonprod.itcmd_rules where uf = upper(p_uf)), 0) + 1, p_rules, p_source, p_notes, auth.uid())
  returning id into v_id;
  return v_id;
end $$;

create or replace function cw_nonprod.itcmd_rule_publish(p_id uuid) returns void
language plpgsql security definer set search_path = '' as $$
begin
  if not cw_nonprod_private.is_master() then perform cw_nonprod_private.deny(); end if;
  update cw_nonprod.itcmd_rules set published_at = now(), published_by = auth.uid() where id = p_id and published_at is null;
  if not found then perform cw_nonprod_private.deny(); end if;
end $$;

create or replace function cw_nonprod.admin_set_retention(p_purpose text, p_days integer, p_note text) returns void
language plpgsql security definer set search_path = '' as $$
begin
  if not cw_nonprod_private.is_master() then perform cw_nonprod_private.deny(); end if;
  update cw_nonprod.document_retention_policies
     set retention_days = p_days, legal_basis_note = left(trim(p_note), 500), updated_at = now(), updated_by = auth.uid()
   where purpose = p_purpose::cw_nonprod.document_purpose;
  perform cw_nonprod_private.write_audit('UPDATE', 'document_retention_policies', p_purpose, null, null,
    jsonb_build_object('retention_days', p_days));
end $$;

create or replace function cw_nonprod.admin_documents_mark_expired() returns table (document_id uuid, storage_path text)
language plpgsql security definer set search_path = '' as $$
begin
  if not cw_nonprod_private.is_master() then perform cw_nonprod_private.deny(); end if;
  return query select * from cw_nonprod.system_documents_mark_expired();
end $$;

create or replace function cw_nonprod.admin_documents_confirm_purged(p_ids uuid[]) returns integer
language plpgsql security definer set search_path = '' as $$
begin
  if not cw_nonprod_private.is_master() then perform cw_nonprod_private.deny(); end if;
  return cw_nonprod.system_documents_confirm_purged(p_ids);
end $$;

-- Queued originals are seen and removed by the platform owner's manual executor (the daily job uses the service role).
create or replace function cw_nonprod_private.storage_document_allowed(p_name text, p_op text) returns boolean
language sql stable security definer set search_path = '' as $$
  select coalesce((
    select case p_op
      when 'INSERT' then d.status = 'PENDING_UPLOAD' and d.uploaded_by = (select auth.uid()) and cw_nonprod_private.can_access_document(d.client_id, d.contact_id)
      when 'SELECT' then (d.status = 'STORED' and cw_nonprod_private.can_access_document(d.client_id, d.contact_id))
                         or (d.status = 'PURGE_PENDING' and cw_nonprod_private.is_master())
      when 'DELETE' then d.status = 'PURGE_PENDING' and cw_nonprod_private.is_master()
      else false end
    from cw_nonprod.documents d where d.storage_path = p_name), false)
$$;

create or replace function cw_nonprod.admin_upsert_global_rule(p_rule uuid, p_pattern text, p_direction text, p_kind text, p_nature text,
                                               p_subcategory text, p_priority integer, p_active boolean) returns uuid
language plpgsql security definer set search_path = '' as $$
declare v_id uuid;
begin
  if not cw_nonprod_private.is_master() then perform cw_nonprod_private.deny(); end if;
  if p_rule is null then
    insert into cw_nonprod.transaction_rules (scope, pattern, direction, account_kind, nature, subcategory, priority, active, created_by)
    values ('GLOBAL', cw_nonprod_private.normalize_merchant(p_pattern), p_direction, p_kind, p_nature::cw_nonprod.txn_nature, p_subcategory,
            p_priority, p_active, auth.uid()) returning id into v_id;
  else
    update cw_nonprod.transaction_rules set pattern = cw_nonprod_private.normalize_merchant(p_pattern), direction = p_direction, account_kind = p_kind,
           nature = p_nature::cw_nonprod.txn_nature, subcategory = p_subcategory, priority = p_priority, active = p_active
     where id = p_rule and scope = 'GLOBAL' returning id into v_id;
    if v_id is null then perform cw_nonprod_private.deny(); end if;
  end if;
  perform cw_nonprod_private.write_audit('UPDATE', 'transaction_rules', v_id::text, null, null,
    jsonb_build_object('pattern', cw_nonprod_private.normalize_merchant(p_pattern), 'nature', p_nature, 'subcategory', p_subcategory, 'active', p_active));
  return v_id;
end $$;

create or replace function cw_nonprod.admin_publish_consent_policy(p_type text, p_body text) returns uuid
language plpgsql security definer set search_path = '' as $$
declare v_id uuid; v_ver int;
begin
  if not cw_nonprod_private.is_master() then perform cw_nonprod_private.deny(); end if;
  select coalesce(max(version), 0) + 1 into v_ver from cw_nonprod.consent_policies where consent_type = p_type;
  insert into cw_nonprod.consent_policies (consent_type, version, body, published_at, created_by)
  values (p_type, v_ver, p_body, now(), auth.uid()) returning id into v_id;
  return v_id;
end $$;

-- ---------------------------------------------------------------- Master: offices, office admins, support
create function cw_nonprod.master_office_save(p_id uuid, p_data jsonb) returns uuid
language plpgsql security definer set search_path = '' as $$
declare v_id uuid;
begin
  if not cw_nonprod_private.is_master() then perform cw_nonprod_private.deny(); end if;
  if p_id is null then
    insert into cw_nonprod.offices (name, legal_name, cnpj, cvm_code, created_by)
    values (btrim(p_data ->> 'name'), nullif(btrim(p_data ->> 'legal_name'), ''), nullif(regexp_replace(coalesce(p_data ->> 'cnpj', ''), '\D', '', 'g'), ''),
            nullif(btrim(p_data ->> 'cvm_code'), ''), auth.uid())
    returning id into v_id;
  else
    update cw_nonprod.offices set name = btrim(p_data ->> 'name'), legal_name = nullif(btrim(p_data ->> 'legal_name'), ''),
           cnpj = nullif(regexp_replace(coalesce(p_data ->> 'cnpj', ''), '\D', '', 'g'), ''), cvm_code = nullif(btrim(p_data ->> 'cvm_code'), ''),
           updated_at = now()
     where id = p_id returning id into v_id;
    if v_id is null then perform cw_nonprod_private.deny(); end if;
  end if;
  return v_id;
end $$;

create function cw_nonprod.master_office_set_status(p_id uuid, p_status text) returns void
language plpgsql security definer set search_path = '' as $$
begin
  if not cw_nonprod_private.is_master() or p_id = cw_nonprod_private.my_office() then perform cw_nonprod_private.deny(); end if; -- never lock yourself out
  update cw_nonprod.offices set status = p_status, updated_at = now() where id = p_id;
  if not found then perform cw_nonprod_private.deny(); end if;
end $$;

create function cw_nonprod.master_office_overview()
returns table (office_id uuid, name text, cnpj text, status text, admins bigint, consultants bigint, assistants bigint, clients bigint, created_at timestamptz)
language plpgsql stable security definer set search_path = '' as $$
begin
  if not cw_nonprod_private.is_master() then perform cw_nonprod_private.deny(); end if;
  return query
  select o.id, o.name, o.cnpj, o.status,
    (select count(*) from cw_nonprod.profiles p where p.office_id = o.id and p.role = 'ADMIN' and p.status <> 'SUSPENDED'),
    (select count(*) from cw_nonprod.profiles p where p.office_id = o.id and p.role = 'CONSULTANT' and p.status <> 'SUSPENDED'),
    (select count(*) from cw_nonprod.profiles p where p.office_id = o.id and p.role = 'ASSISTANT' and p.status <> 'SUSPENDED'),
    (select count(*) from cw_nonprod.clients c where c.office_id = o.id and c.status = 'ACTIVE' and not c.is_prospect),
    o.created_at
  from cw_nonprod.offices o order by o.name;
end $$;

-- Staff of an office (names, e-mails, roles): what the platform owner needs to support the office, no client data.
create function cw_nonprod.master_office_staff(p_office uuid)
returns table (user_id uuid, full_name text, email text, role text, status text)
language plpgsql stable security definer set search_path = '' as $$
begin
  if not cw_nonprod_private.is_master() then perform cw_nonprod_private.deny(); end if;
  return query select p.id, p.full_name, p.email, p.role::text, p.status::text from cw_nonprod.profiles p
   where p.office_id = p_office and p.role <> 'CLIENT' order by p.role, p.full_name;
end $$;

-- The first ADMIN of an office (and later ones, when the office asks the platform).
create function cw_nonprod.master_invite_office_admin(p_office uuid, p_email text) returns uuid
language plpgsql security definer set search_path = '' as $$
declare v_email text := lower(trim(p_email)); v_id uuid;
begin
  if not cw_nonprod_private.is_master() or not exists (select 1 from cw_nonprod.offices where id = p_office and status = 'ACTIVE') then perform cw_nonprod_private.deny(); end if;
  if v_email is null or v_email !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' then raise exception 'invalid email' using errcode = '22023'; end if;
  update cw_nonprod.invitations set status = 'REVOKED', revoked_at = now(), revoked_by = auth.uid()
   where email = v_email and status = 'PENDING' and expires_at <= now();
  -- the guard checks the inviter's office; the platform owner invites into another office as platform operation
  perform set_config('cw.master_invite', 'on', true);
  insert into cw_nonprod.invitations (email, role, client_id, invited_by, office_id)
  values (v_email, 'ADMIN', null, auth.uid(), p_office) returning id into v_id;
  perform set_config('cw.master_invite', '', true);
  perform cw_nonprod_private.write_audit('INVITE_CREATED', 'invitations', v_id::text, null, null, jsonb_build_object('role', 'ADMIN', 'office_id', p_office));
  return v_id;
end $$;

create function cw_nonprod.master_support_start(p_office uuid, p_reason text, p_minutes integer) returns uuid
language plpgsql security definer set search_path = '' as $$
declare v_id uuid;
begin
  if not cw_nonprod_private.is_master() or p_minutes not between 5 and 120 then perform cw_nonprod_private.deny(); end if;
  update cw_nonprod_private.support_sessions set ended_at = now() where master_id = auth.uid() and ended_at is null;
  insert into cw_nonprod_private.support_sessions (master_id, office_id, reason, expires_at)
  values (auth.uid(), p_office, btrim(p_reason), now() + make_interval(mins => p_minutes)) returning id into v_id;
  perform cw_nonprod_private.write_audit('ADMIN_SUPPORT_ACCESS', 'offices', p_office::text, null, null,
    jsonb_build_object('session', v_id, 'reason', btrim(p_reason), 'minutes', p_minutes));
  return v_id;
end $$;

create function cw_nonprod.master_support_end() returns void
language plpgsql security definer set search_path = '' as $$
begin
  if not cw_nonprod_private.is_master() then perform cw_nonprod_private.deny(); end if;
  update cw_nonprod_private.support_sessions set ended_at = now() where master_id = auth.uid() and ended_at is null;
end $$;

create function cw_nonprod.master_support_sessions()
returns table (id uuid, office_name text, reason text, started_at timestamptz, expires_at timestamptz, ended_at timestamptz)
language plpgsql stable security definer set search_path = '' as $$
begin
  if not cw_nonprod_private.is_master() then perform cw_nonprod_private.deny(); end if;
  return query select s.id, o.name, s.reason, s.started_at, s.expires_at, s.ended_at
    from cw_nonprod_private.support_sessions s join cw_nonprod.offices o on o.id = s.office_id
   where s.master_id = auth.uid() order by s.started_at desc limit 50;
end $$;

-- Who am I (for the app shell): office name and whether the platform flag is on (never other people's data).
create function cw_nonprod.my_context() returns table (office_id uuid, office_name text, platform_master boolean, support_office uuid)
language sql stable security definer set search_path = '' as $$
  select o.id, o.name, p.platform_master,
    (select s.office_id from cw_nonprod_private.support_sessions s where s.master_id = p.id and s.ended_at is null and s.expires_at > now() limit 1)
  from cw_nonprod.profiles p join cw_nonprod.offices o on o.id = p.office_id where p.id = (select auth.uid())
$$;

-- The master invite path skips the "inviter's office" rule (and only that one).
create or replace function cw_nonprod_private.guard_office() returns trigger
language plpgsql security definer set search_path = '' as $$
declare v_office uuid; v_other uuid;
begin
  if auth.uid() is null then return new; end if;
  if tg_op = 'UPDATE' and tg_table_name in ('profiles', 'clients', 'crm_contacts', 'invitations') then
    if new.office_id is distinct from old.office_id then raise exception 'office cannot change' using errcode = '42501'; end if;
  end if;
  if tg_table_name = 'profiles' and tg_op = 'UPDATE' then
    if new.platform_master is distinct from old.platform_master then raise exception 'protected profile fields' using errcode = '42501'; end if;
  end if;
  if tg_table_name = 'invitations' and tg_op = 'INSERT' then
    if coalesce(current_setting('cw.master_invite', true), '') = 'on' and cw_nonprod_private.is_master() and new.role = 'ADMIN' then return new; end if;
  end if;
  -- one branch per table: a record field that the table does not have must never be referenced
  if tg_table_name = 'consultant_client_access' then
    v_office := (select office_id from cw_nonprod.clients where id = new.client_id); v_other := cw_nonprod_private.office_of_user(new.consultant_id);
  elsif tg_table_name = 'client_users' then
    v_office := (select office_id from cw_nonprod.clients where id = new.client_id); v_other := cw_nonprod_private.office_of_user(new.user_id);
  elsif tg_table_name = 'user_permissions' then
    v_office := cw_nonprod_private.office_of_user(new.user_id); v_other := v_office;
  elsif tg_table_name = 'crm_contacts' then
    v_office := new.office_id; v_other := cw_nonprod_private.office_of_user(new.owner_id);
  else
    v_office := new.office_id; v_other := v_office;
  end if;
  if v_office is distinct from v_other then raise exception 'cross-office link' using errcode = '42501'; end if;
  -- the person themself: own profile, accepting own invitation, own client link (office already matched above)
  if tg_table_name = 'profiles' then
    if new.id = auth.uid() then return new; end if;
  elsif tg_table_name = 'invitations' then
    if new.auth_user_id = auth.uid() then return new; end if;
    if new.invited_by = auth.uid() and cw_nonprod_private.is_master() then return new; end if; -- binds/revokes the office admin it invited
  elsif tg_table_name = 'client_users' then
    if new.user_id = auth.uid() then return new; end if;
  end if;
  if v_office is distinct from cw_nonprod_private.my_office() and not cw_nonprod_private.support_access(v_office) then
    raise exception 'other office' using errcode = '42501';
  end if;
  return new;
end $$;

revoke all on function cw_nonprod_private.my_office(), cw_nonprod_private.office_of_user(uuid), cw_nonprod_private.is_master(), cw_nonprod_private.support_access(uuid),
  cw_nonprod_private.stamp_office(), cw_nonprod_private.stamp_profile_office(), cw_nonprod_private.guard_office() from public, anon;
grant execute on function cw_nonprod_private.my_office(), cw_nonprod_private.office_of_user(uuid), cw_nonprod_private.is_master(), cw_nonprod_private.support_access(uuid) to authenticated;
revoke all on function cw_nonprod_private.stamp_office(), cw_nonprod_private.stamp_profile_office(), cw_nonprod_private.guard_office() from authenticated;
revoke all on function cw_nonprod.master_office_save(uuid, jsonb), cw_nonprod.master_office_set_status(uuid, text), cw_nonprod.master_office_overview(),
  cw_nonprod.master_office_staff(uuid), cw_nonprod.master_invite_office_admin(uuid, text), cw_nonprod.master_support_start(uuid, text, integer),
  cw_nonprod.master_support_end(), cw_nonprod.master_support_sessions(), cw_nonprod.my_context() from public, anon;
grant execute on function cw_nonprod.master_office_save(uuid, jsonb), cw_nonprod.master_office_set_status(uuid, text), cw_nonprod.master_office_overview(),
  cw_nonprod.master_office_staff(uuid), cw_nonprod.master_invite_office_admin(uuid, text), cw_nonprod.master_support_start(uuid, text, integer),
  cw_nonprod.master_support_end(), cw_nonprod.master_support_sessions(), cw_nonprod.my_context() to authenticated;
commit;
select 'migrações 30-31 ok' as resultado, (select count(*) from cw_nonprod.offices) as escritorios, (select count(*) from cw_nonprod.profiles where office_id is null) as perfis_sem_escritorio, (select count(*) from cw_nonprod.clients where office_id is null) as clientes_sem_escritorio, (select count(*) from cw_nonprod.profiles where platform_master) as donos_da_plataforma;
